function test_stage4a6_1_profile_metrics()
%TEST_STAGE4A6_1_PROFILE_METRICS Profile reliability and NaN semantics.
    model=calibrate_stage4a6_1_parameter_domain(repmat(evidence(),2,1),struct('parameter_calibration',struct('minimum_samples',3,'improvement_quantile',.95,'relative_improvement_quantile',.95,'sensitivity_floor_quantile',.05),'optimization',struct('boundary_fraction',.05)),.5,'h');assert(strcmp(model.calibration_status,'insufficient_calibration') && ~model.calibration_valid,'Insufficient profiles must not create thresholds.');d=struct('method_id','A6_1_M0_topology_only','topology_status','unique_topology','topology_set','G001','grid_id','A','replicate_id','r','optimizer_converged',false,'profile_reliable',false,'parameter_domain_status','parameter_not_evaluated');l=struct('grid_id','A','replicate_id','r','category','parameter_in_domain','outlier_dimension','','outlier_severity','','truth_topology_id','G001','truth_is_nonunique',false,'parameter_domain_truth','in_domain');m=evaluate_stage4a6_1_metrics(d,l);assert(isnan(m.parameter_ood_recall) && strcmp(m.parameter_status,'not_applicable'),'M0 parameter metrics must be NaN/not_applicable.');fprintf('ALL STAGE 4A.6.1 PROFILE/METRIC TESTS PASSED\n');
end
function e=evidence(),e=struct('profile_reliable',false,'lambda',NaN,'relative_improvement',NaN,'minimum_sensitivity',NaN);end
